import json, os

inp = os.environ["INPUT_DIR"]
with open(os.path.join(inp, "ders_programi.json"), encoding="utf-8") as f:
    prog = json.load(f)

HEDEF_AD = "İşletim Sistemleri I"
HEDEF_SUBE = "B"

def to_min(hhmm):
    h, m = hhmm.strip().split(":")
    return int(h) * 60 + int(m)

def aralik(s):
    a, b = s.split("-")
    return to_min(a), to_min(b)

dersler = prog["dersler"]

# Hedef dersin B şubesi (ad eşleşmesi; büyük/küçük harf ve boşluk toleranslı)
norm = lambda s: " ".join(str(s).split()).casefold()
hedefler = [d for d in dersler
            if norm(d.get("ders", "")) == norm(HEDEF_AD)
            and str(d.get("sube", "")).strip().upper() == HEDEF_SUBE]

print("=== Hedef ders (B şubesi) kayıtları ===")
for d in hedefler:
    print(json.dumps(d, ensure_ascii=False))

if not hedefler:
    print("HATA: B şubesi bulunamadı.")
    raise SystemExit(1)

# Aynı adlı dersin tüm şubeleri (bilgi amaçlı)
print("\n=== '%s' dersinin tüm şubeleri ===" % HEDEF_AD)
for d in dersler:
    if norm(d.get("ders", "")) == norm(HEDEF_AD):
        print(d.get("sube"), d.get("gun"), d.get("saatler"), d.get("derslik"))

print("\n=== Çakışma kontrolü ===")
bulunan = []
for h in hedefler:
    hg = h["gun"]
    hs = [aralik(s) for s in h["saatler"]]
    for d in dersler:
        if d is h or d.get("gun") != hg:
            continue
        # Aynı kayıt değilse (kod+şube+gün) karşılaştır
        if d.get("kod") == h.get("kod") and d.get("sube") == h.get("sube"):
            continue
        for s in d.get("saatler", []):
            a, b = aralik(s)
            for x, y in hs:
                if a < y and x < b:  # zaman aralıkları kesişiyor
                    bulunan.append((h, d, s))
                    break

if not bulunan:
    print("Çakışan ders bulunmadı.")
else:
    for h, d, s in bulunan:
        print("ÇAKIŞMA: %s (%s şubesi, %s, %s) <-> %s (%s şubesi, %s, %s) [%s]" % (
            h["ders"], h["sube"], h["gun"], h["saatler"],
            d["ders"], d.get("sube"), d["gun"], d.get("saatler"), s))
